BEGIN;
DO $$
DECLARE
  v_subject_id UUID;
  v_topic_id UUID;
  v_test_id BIGINT;
BEGIN
  SELECT id INTO v_subject_id FROM test_subjects WHERE name ILIKE '%cardio%' ORDER BY id LIMIT 1;
  IF v_subject_id IS NULL THEN
    INSERT INTO test_subjects (name, description) VALUES ('Cardiovascular System', 'Cardiovascular notes') RETURNING id INTO v_subject_id;
  END IF;
  SELECT id INTO v_topic_id FROM test_topics WHERE name = 'Shock Management' ORDER BY (SELECT COUNT(*) FROM test_questions q WHERE q.topic_id = test_topics.id) DESC, created_at ASC LIMIT 1;
  IF v_topic_id IS NULL THEN
    INSERT INTO test_topics (subject_id, name, description, status) VALUES (v_subject_id, 'Shock Management', 'Shock types, recognition, and targeted treatment', 'published') RETURNING id INTO v_topic_id;
  END IF;
  SELECT id INTO v_test_id FROM tests WHERE is_active = true ORDER BY id LIMIT 1;
  IF v_test_id IS NULL THEN
    INSERT INTO tests (test_name, system_category, description, is_active)
    VALUES ('Cardiovascular System - Shock Management (Generated)', 'Cardiovascular System', 'Auto-generated NCLEX question set', true)
    RETURNING id INTO v_test_id;
  END IF;
  DELETE FROM test_questions WHERE topic_id = v_topic_id AND category = 'Shock Management - NCLEX';
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Shock Management note, which statement about "Shock definition" is most accurate?', 'According to the Shock Management note, which statement about "Shock definition" is most accurate?', '[{"id": "a", "text": "Shock has no effect on oxygen delivery."}, {"id": "b", "text": "Late shock preserves normal mentation."}, {"id": "c", "text": "Shock reflects inadequate tissue perfusion."}, {"id": "d", "text": "Shock is defined as isolated hypertension."}]'::jsonb, '["c"]'::jsonb, 'Correct because Shock is inadequate tissue perfusion causing insufficient oxygen delivery and cellular dysfunction. Treat perfusion failure early to prevent irreversible organ injury.', 'Shock Management - NCLEX', false, 1, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Shock metabolic pathway" in Shock Management. Which statement is correct?', 'The nurse is reviewing "Shock metabolic pathway" in Shock Management. Which statement is correct?', '[{"id": "a", "text": "Shock cannot cause organ dysfunction."}, {"id": "b", "text": "Septic shock always has high SVR."}, {"id": "c", "text": "Normal BP definitively excludes shock."}, {"id": "d", "text": "Anaerobic metabolism occurs in shock."}]'::jsonb, '["d"]'::jsonb, 'Correct because In shock, anaerobic metabolism develops with lactic acidosis and can progress to MODS. Track lactate and organ function to detect decompensation early.', 'Shock Management - NCLEX', false, 2, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Hypovolemic profile" in Shock Management?', 'Which clinical judgment is most accurate regarding "Hypovolemic profile" in Shock Management?', '[{"id": "a", "text": "Hypovolemic shock has high CO and low SVR."}, {"id": "b", "text": "Shock subtype is irrelevant once oxygen is started."}, {"id": "c", "text": "Monitoring can be delayed until subtype confirmed."}, {"id": "d", "text": "SVR increases compensatorily in hypovolemic shock."}]'::jsonb, '["d"]'::jsonb, 'Correct because Hypovolemic shock stems from blood/fluid loss with low CO, high SVR, flat neck veins, pallor, and tachycardia. Rapid volume replacement and bleeding control are primary priorities.', 'Shock Management - NCLEX', false, 3, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Cardiogenic profile" in Shock Management?', 'In rapid prioritization, which statement is most consistent with "Cardiogenic profile" in Shock Management?', '[{"id": "a", "text": "Obstructive shock is caused by volume loss only."}, {"id": "b", "text": "S3/frothy sputum are associated findings."}, {"id": "c", "text": "Hypotension is first sign of shock."}, {"id": "d", "text": "Cardiogenic shock presents with flat neck veins."}]'::jsonb, '["b"]'::jsonb, 'Correct because Cardiogenic shock is pump failure (e.g., MI/HF/cardiomyopathy) with low CO, high SVR, JVD, crackles, S3, and frothy sputum. Support contractility and address the primary cardiac lesion urgently.', 'Shock Management - NCLEX', false, 4, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Septic profile" in Shock Management would the nurse recognize as correct?', 'Which conclusion about "Septic profile" in Shock Management would the nurse recognize as correct?', '[{"id": "a", "text": "Skin is cold/clammy from onset in all septic phases."}, {"id": "b", "text": "Shock subtype is irrelevant once oxygen is started."}, {"id": "c", "text": "Urine output monitoring is optional in shock."}, {"id": "d", "text": "Septic shock is distributive with vasodilation."}]'::jsonb, '["d"]'::jsonb, 'Correct because Septic shock is distributive vasodilation with low SVR and warm flushed skin early; CO may be high early then low late. Initiate sepsis bundle quickly before transition to late hypodynamic phase.', 'Shock Management - NCLEX', false, 5, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Shock Management note, which statement about "Neurogenic profile" is most accurate?', 'According to the Shock Management note, which statement about "Neurogenic profile" is most accurate?', '[{"id": "a", "text": "Loss of sympathetic tone is mechanism."}, {"id": "b", "text": "Neurogenic shock usually causes tachycardia."}, {"id": "c", "text": "Normal BP definitively excludes shock."}, {"id": "d", "text": "Late shock has improving urine output."}]'::jsonb, '["a"]'::jsonb, 'Correct because Neurogenic shock follows spinal injury with loss of sympathetic tone causing low CO, low SVR, bradycardia, hypotension, and warm dry skin below injury. Recognize bradycardia-hypotension pattern as distinguishing feature.', 'Shock Management - NCLEX', false, 6, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Obstructive profile" in Shock Management. Which statement is correct?', 'The nurse is reviewing "Obstructive profile" in Shock Management. Which statement is correct?', '[{"id": "a", "text": "Obstructive shock is caused by volume loss only."}, {"id": "b", "text": "Shock subtype is irrelevant once oxygen is started."}, {"id": "c", "text": "Blood pressure normalization alone confirms full recovery."}, {"id": "d", "text": "Definitive relief of obstruction is mandatory for recovery."}]'::jsonb, '["d"]'::jsonb, 'Correct because Obstructive shock is due to physical flow obstruction (tamponade, tension PTX, PE) with low CO and high SVR. Definitive relief of obstruction is mandatory for recovery.', 'Shock Management - NCLEX', false, 7, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Early shock signs" in Shock Management?', 'Which clinical judgment is most accurate regarding "Early shock signs" in Shock Management?', '[{"id": "a", "text": "Shock treatment begins with oral fluids only."}, {"id": "b", "text": "Hypotension is first sign of shock."}, {"id": "c", "text": "Cool clammy skin and tachypnea are early signs."}, {"id": "d", "text": "All shock types should use strict Trendelenburg."}]'::jsonb, '["c"]'::jsonb, 'Correct because Early compensated shock shows tachycardia first, possible normal BP, cool clammy skin, tachypnea, anxiety, and slight urine decrease. Do not be reassured by normal BP when compensatory signs are present.', 'Shock Management - NCLEX', false, 8, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Late shock signs" in Shock Management?', 'In rapid prioritization, which statement is most consistent with "Late shock signs" in Shock Management?', '[{"id": "a", "text": "Late shock preserves normal mentation."}, {"id": "b", "text": "Late shock has improving urine output."}, {"id": "c", "text": "Urine output monitoring is optional in shock."}, {"id": "d", "text": "Urine output under 30 mL/hr is late sign."}]'::jsonb, '["d"]'::jsonb, 'Correct because Late decompensated shock includes hypotension, altered LOC, urine output <30 mL/hr, mottled/cyanotic skin, lactic acidosis, and MODS progression. Escalate aggressively at decompensation to prevent arrest.', 'Shock Management - NCLEX', false, 9, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "NCLEX early warning" in Shock Management would the nurse recognize as correct?', 'Which conclusion about "NCLEX early warning" in Shock Management would the nurse recognize as correct?', '[{"id": "a", "text": "Shock subtype is irrelevant once oxygen is started."}, {"id": "b", "text": "Invasive lines are contraindicated in severe shock."}, {"id": "c", "text": "Prioritize trend recognition over single BP value."}, {"id": "d", "text": "Bradycardia is first universal shock sign."}]'::jsonb, '["c"]'::jsonb, 'Correct because NCLEX priority notes that tachycardia is first and BP drops last, so normal BP does not rule out shock. Prioritize trend recognition over single BP value.', 'Shock Management - NCLEX', false, 10, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Shock Management note, which statement about "General initial treatment" is most accurate?', 'According to the Shock Management note, which statement about "General initial treatment" is most accurate?', '[{"id": "a", "text": "Invasive lines are contraindicated in severe shock."}, {"id": "b", "text": "Monitoring can be delayed until subtype confirmed."}, {"id": "c", "text": "Shock subtype is irrelevant once oxygen is started."}, {"id": "d", "text": "Continuous vitals/SpO2/urine monitoring is required."}]'::jsonb, '["d"]'::jsonb, 'Correct because General treatment includes oxygenation, large-bore IV access, continuous monitoring, urine output goals, and broad shock labs. Rapid stabilization and monitoring should start before definitive subtype treatment.', 'Shock Management - NCLEX', false, 11, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Positioning rule" in Shock Management. Which statement is correct?', 'The nurse is reviewing "Positioning rule" in Shock Management. Which statement is correct?', '[{"id": "a", "text": "Shock subtype is irrelevant once oxygen is started."}, {"id": "b", "text": "Cardiogenic shock requires leg elevation above heart."}, {"id": "c", "text": "All shock types should use strict Trendelenburg."}, {"id": "d", "text": "Cardiogenic shock is exception with HOB elevation."}]'::jsonb, '["d"]'::jsonb, 'Correct because Shock positioning is generally supine with legs elevated (Trendelenburg/modified), except cardiogenic shock where HOB is elevated. Choose position by shock type to avoid worsening pulmonary congestion.', 'Shock Management - NCLEX', false, 12, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Urine output target" in Shock Management?', 'Which clinical judgment is most accurate regarding "Urine output target" in Shock Management?', '[{"id": "a", "text": "Pericardiocentesis is contraindicated in tamponade."}, {"id": "b", "text": "Urine output monitoring is optional in shock."}, {"id": "c", "text": "Obstructive shock is corrected by fluids alone."}, {"id": "d", "text": "Foley is recommended for hourly urine monitoring."}]'::jsonb, '["d"]'::jsonb, 'Correct because Foley monitoring goal is urine output greater than 0.5 mL/kg/hr. Renal perfusion tracking is critical in shock resuscitation.', 'Shock Management - NCLEX', false, 13, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Severe shock invasive monitoring" in Shock Management?', 'In rapid prioritization, which statement is most consistent with "Severe shock invasive monitoring" in Shock Management?', '[{"id": "a", "text": "Invasive lines are contraindicated in severe shock."}, {"id": "b", "text": "Antibiotics are delayed until cultures finalize."}, {"id": "c", "text": "Shock subtype is irrelevant once oxygen is started."}, {"id": "d", "text": "Invasive monitoring supports advanced management."}]'::jsonb, '["d"]'::jsonb, 'Correct because Arterial and central lines are used in severe shock for close hemodynamic management. Use invasive monitoring when rapid titration is needed.', 'Shock Management - NCLEX', false, 14, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Shock lab panel" in Shock Management would the nurse recognize as correct?', 'Which conclusion about "Shock lab panel" in Shock Management would the nurse recognize as correct?', '[{"id": "a", "text": "Fluid bolus is contraindicated in septic shock."}, {"id": "b", "text": "Blood cultures are included for sepsis context."}, {"id": "c", "text": "No labs are needed during shock."}, {"id": "d", "text": "Dobutamine alone is first-line septic pressor."}]'::jsonb, '["b"]'::jsonb, 'Correct because Recommended labs include ABG, lactate, CBC, BMP, coagulation tests, and blood cultures in sepsis. Combine perfusion, metabolic, and infectious data quickly.', 'Shock Management - NCLEX', false, 15, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Shock Management note, which statement about "Hypovolemic treatment specifics" is most accurate?', 'According to the Shock Management note, which statement about "Hypovolemic treatment specifics" is most accurate?', '[{"id": "a", "text": "No vasopressors before adequate volume is key point."}, {"id": "b", "text": "Shock subtype is irrelevant once oxygen is started."}, {"id": "c", "text": "Vasopressors are first-line before fluids in hypovolemia."}, {"id": "d", "text": "Epinephrine has no cardiovascular receptor effects."}]'::jsonb, '["a"]'::jsonb, 'Correct because Hypovolemic treatment is IV crystalloids (NS/LR), blood products if hemorrhagic, bleeding control, and delaying vasopressors until volume replacement. Restore intravascular volume before vasoconstriction strategies.', 'Shock Management - NCLEX', false, 16, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Cardiogenic treatment specifics" in Shock Management. Which statement is correct?', 'The nurse is reviewing "Cardiogenic treatment specifics" in Shock Management. Which statement is correct?', '[{"id": "a", "text": "Cardiogenic shock is treated with volume loading only."}, {"id": "b", "text": "Norepinephrine may be added if hypotension persists."}, {"id": "c", "text": "Shock subtype is irrelevant once oxygen is started."}, {"id": "d", "text": "Inotropes are contraindicated in cardiogenic shock."}]'::jsonb, '["b"]'::jsonb, 'Correct because Cardiogenic management includes treating cause (e.g., PCI for MI), inotropes (dobutamine/milrinone), norepinephrine if persistent hypotension, diuretics if overloaded, and possible IABP/LVAD. Support pump function while correcting primary cardiac pathology.', 'Shock Management - NCLEX', false, 17, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Septic bundle timing" in Shock Management?', 'Which clinical judgment is most accurate regarding "Septic bundle timing" in Shock Management?', '[{"id": "a", "text": "Norepinephrine is pure β2 bronchodilator."}, {"id": "b", "text": "All shock is treated identically long-term."}, {"id": "c", "text": "Fluid bolus is contraindicated in septic shock."}, {"id": "d", "text": "Cultures are obtained before antibiotics."}]'::jsonb, '["d"]'::jsonb, 'Correct because Septic shock care includes blood cultures before antibiotics, broad-spectrum antibiotics within 1 hour, and 30 mL/kg fluid bolus within 3 hours. Time-sensitive sepsis actions strongly influence outcomes.', 'Shock Management - NCLEX', false, 18, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Septic vasopressors/steroids" in Shock Management?', 'In rapid prioritization, which statement is most consistent with "Septic vasopressors/steroids" in Shock Management?', '[{"id": "a", "text": "Shock subtype is irrelevant once oxygen is started."}, {"id": "b", "text": "Dobutamine alone is first-line septic pressor."}, {"id": "c", "text": "Steroids are always first treatment before fluids."}, {"id": "d", "text": "Steroids are considered in refractory septic shock."}]'::jsonb, '["d"]'::jsonb, 'Correct because Norepinephrine is first-line vasopressor in septic shock, with corticosteroids considered if refractory. Escalate pressor support and adjuncts when fluid response is inadequate.', 'Shock Management - NCLEX', false, 19, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Neurogenic treatment specifics" in Shock Management would the nurse recognize as correct?', 'Which conclusion about "Neurogenic treatment specifics" in Shock Management would the nurse recognize as correct?', '[{"id": "a", "text": "Shock subtype is irrelevant once oxygen is started."}, {"id": "b", "text": "Address vasodilation and bradycardia while protecting spinal injury."}, {"id": "c", "text": "Blood pressure normalization alone confirms full recovery."}, {"id": "d", "text": "Neurogenic shock requires no vasopressors."}]'::jsonb, '["b"]'::jsonb, 'Correct because Neurogenic shock treatment includes cautious fluids, norepinephrine/phenylephrine, atropine for bradycardia, and spinal immobilization. Address vasodilation and bradycardia while protecting spinal injury.', 'Shock Management - NCLEX', false, 20, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Shock Management note, which statement about "Obstructive definitive care" is most accurate?', 'According to the Shock Management note, which statement about "Obstructive definitive care" is most accurate?', '[{"id": "a", "text": "Pericardiocentesis is contraindicated in tamponade."}, {"id": "b", "text": "Tension PTX needs needle decompression at 2nd ICS MCL."}, {"id": "c", "text": "Epinephrine has no cardiovascular receptor effects."}, {"id": "d", "text": "Shock subtype is irrelevant once oxygen is started."}]'::jsonb, '["b"]'::jsonb, 'Correct because Obstructive shock requires removing obstruction: pericardiocentesis for tamponade, needle decompression for tension PTX, and thrombolysis/embolectomy for PE. Definitive mechanical relief is essential; supportive measures alone are insufficient.', 'Shock Management - NCLEX', false, 21, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Norepinephrine profile" in Shock Management. Which statement is correct?', 'The nurse is reviewing "Norepinephrine profile" in Shock Management. Which statement is correct?', '[{"id": "a", "text": "Blood pressure normalization alone confirms full recovery."}, {"id": "b", "text": "Monitor peripheral perfusion while titrating SVR support."}, {"id": "c", "text": "Shock subtype is irrelevant once oxygen is started."}, {"id": "d", "text": "Norepinephrine is pure β2 bronchodilator."}]'::jsonb, '["b"]'::jsonb, 'Correct because Norepinephrine acts via α1 + β1 to increase SVR with mild CO effect and is first-line for septic shock; also used in neurogenic shock. Monitor peripheral perfusion while titrating SVR support.', 'Shock Management - NCLEX', false, 22, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Dobutamine profile" in Shock Management?', 'Which clinical judgment is most accurate regarding "Dobutamine profile" in Shock Management?', '[{"id": "a", "text": "All shock is treated identically long-term."}, {"id": "b", "text": "Dobutamine is first-line for anaphylaxis."}, {"id": "c", "text": "Shock is defined as isolated hypertension."}, {"id": "d", "text": "Used for cardiogenic shock with low EF."}]'::jsonb, '["d"]'::jsonb, 'Correct because Dobutamine is a β1 inotrope increasing contractility and is used in cardiogenic shock with reduced EF. Use inotropy to augment forward flow in pump failure.', 'Shock Management - NCLEX', false, 23, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Epinephrine and vasopressin profiles" in Shock Management?', 'In rapid prioritization, which statement is most consistent with "Epinephrine and vasopressin profiles" in Shock Management?', '[{"id": "a", "text": "Shock subtype is irrelevant once oxygen is started."}, {"id": "b", "text": "Epinephrine has no cardiovascular receptor effects."}, {"id": "c", "text": "Vasopressin is septic add-on via V1 vasoconstriction."}, {"id": "d", "text": "Blood pressure normalization alone confirms full recovery."}]'::jsonb, '["c"]'::jsonb, 'Correct because Epinephrine is α1/β1/β2 and used in anaphylaxis/cardiac arrest, while vasopressin (V1) is septic add-on vasoconstrictor. Match pressor receptor profile to clinical indication.', 'Shock Management - NCLEX', false, 24, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Shock-type mnemonic" in Shock Management would the nurse recognize as correct?', 'Which conclusion about "Shock-type mnemonic" in Shock Management would the nurse recognize as correct?', '[{"id": "a", "text": "Use simple mechanistic labels to speed differentiation and treatment selection."}, {"id": "b", "text": "Blood pressure normalization alone confirms full recovery."}, {"id": "c", "text": "Shock subtype is irrelevant once oxygen is started."}, {"id": "d", "text": "Distributive is blocked exit."}]'::jsonb, '["a"]'::jsonb, 'Correct because Mnemonic in note: H hypovolemic (empty tank), C cardiogenic (broken pump), D distributive (leaky pipes), O obstructive (blocked exit). Use simple mechanistic labels to speed differentiation and treatment selection.', 'Shock Management - NCLEX', false, 25, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Shock Management note, which statement about "Integrated NCLEX triage" is most accurate?', 'According to the Shock Management note, which statement about "Integrated NCLEX triage" is most accurate?', '[{"id": "a", "text": "Compensated shock can present before BP drop."}, {"id": "b", "text": "Hypotension must appear before any intervention."}, {"id": "c", "text": "All shock is treated identically long-term."}, {"id": "d", "text": "Cardiogenic shock presents with flat neck veins."}]'::jsonb, '["a"]'::jsonb, 'Correct because Early shock recognition hinges on tachycardia/tachypnea/anxiety before hypotension, with subtype-targeted definitive management thereafter. Identify compensated shock early and tailor treatment by mechanism.', 'Shock Management - NCLEX', false, 26, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Shock definition" in Shock Management. Which statement is correct?', 'The nurse is reviewing "Shock definition" in Shock Management. Which statement is correct?', '[{"id": "a", "text": "Cardiogenic shock presents with flat neck veins."}, {"id": "b", "text": "Shock reflects inadequate tissue perfusion."}, {"id": "c", "text": "Shock is defined as isolated hypertension."}, {"id": "d", "text": "Shock has no effect on oxygen delivery."}]'::jsonb, '["b"]'::jsonb, 'Correct because Shock is inadequate tissue perfusion causing insufficient oxygen delivery and cellular dysfunction. Treat perfusion failure early to prevent irreversible organ injury.', 'Shock Management - NCLEX', false, 27, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Shock metabolic pathway" in Shock Management?', 'Which clinical judgment is most accurate regarding "Shock metabolic pathway" in Shock Management?', '[{"id": "a", "text": "Blood pressure normalization alone confirms full recovery."}, {"id": "b", "text": "Shock produces alkalosis from hyperperfusion."}, {"id": "c", "text": "Skin is cold/clammy from onset in all septic phases."}, {"id": "d", "text": "Track lactate and organ function to detect decompensation early."}]'::jsonb, '["d"]'::jsonb, 'Correct because In shock, anaerobic metabolism develops with lactic acidosis and can progress to MODS. Track lactate and organ function to detect decompensation early.', 'Shock Management - NCLEX', false, 28, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Hypovolemic profile" in Shock Management?', 'In rapid prioritization, which statement is most consistent with "Hypovolemic profile" in Shock Management?', '[{"id": "a", "text": "Rapid volume replacement and bleeding control are primary priorities."}, {"id": "b", "text": "Hypovolemic shock has high CO and low SVR."}, {"id": "c", "text": "Blood pressure normalization alone confirms full recovery."}, {"id": "d", "text": "Shock subtype is irrelevant once oxygen is started."}]'::jsonb, '["a"]'::jsonb, 'Correct because Hypovolemic shock stems from blood/fluid loss with low CO, high SVR, flat neck veins, pallor, and tachycardia. Rapid volume replacement and bleeding control are primary priorities.', 'Shock Management - NCLEX', false, 29, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Cardiogenic profile" in Shock Management would the nurse recognize as correct?', 'Which conclusion about "Cardiogenic profile" in Shock Management would the nurse recognize as correct?', '[{"id": "a", "text": "Cardiogenic shock presents with flat neck veins."}, {"id": "b", "text": "Cardiogenic shock requires leg elevation above heart."}, {"id": "c", "text": "Support contractility and address the primary cardiac lesion urgently."}, {"id": "d", "text": "Blood pressure normalization alone confirms full recovery."}]'::jsonb, '["c"]'::jsonb, 'Correct because Cardiogenic shock is pump failure (e.g., MI/HF/cardiomyopathy) with low CO, high SVR, JVD, crackles, S3, and frothy sputum. Support contractility and address the primary cardiac lesion urgently.', 'Shock Management - NCLEX', false, 30, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Shock Management note, which statement about "Septic profile" is most accurate?', 'According to the Shock Management note, which statement about "Septic profile" is most accurate?', '[{"id": "a", "text": "Shock subtype is irrelevant once oxygen is started."}, {"id": "b", "text": "Initiate sepsis bundle quickly before transition to late hypodynamic phase."}, {"id": "c", "text": "Blood pressure normalization alone confirms full recovery."}, {"id": "d", "text": "Skin is cold/clammy from onset in all septic phases."}]'::jsonb, '["b"]'::jsonb, 'Correct because Septic shock is distributive vasodilation with low SVR and warm flushed skin early; CO may be high early then low late. Initiate sepsis bundle quickly before transition to late hypodynamic phase.', 'Shock Management - NCLEX', false, 31, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Neurogenic profile" in Shock Management. Which statement is correct?', 'The nurse is reviewing "Neurogenic profile" in Shock Management. Which statement is correct?', '[{"id": "a", "text": "Neurogenic shock includes bradycardia and hypotension."}, {"id": "b", "text": "Invasive lines are contraindicated in severe shock."}, {"id": "c", "text": "Shock subtype is irrelevant once oxygen is started."}, {"id": "d", "text": "Neurogenic shock usually causes tachycardia."}]'::jsonb, '["a"]'::jsonb, 'Correct because Neurogenic shock follows spinal injury with loss of sympathetic tone causing low CO, low SVR, bradycardia, hypotension, and warm dry skin below injury. Recognize bradycardia-hypotension pattern as distinguishing feature.', 'Shock Management - NCLEX', false, 32, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Obstructive profile" in Shock Management?', 'Which clinical judgment is most accurate regarding "Obstructive profile" in Shock Management?', '[{"id": "a", "text": "Obstructive shock is caused by volume loss only."}, {"id": "b", "text": "Blood pressure normalization alone confirms full recovery."}, {"id": "c", "text": "Definitive relief of obstruction is mandatory for recovery."}, {"id": "d", "text": "Shock subtype is irrelevant once oxygen is started."}]'::jsonb, '["c"]'::jsonb, 'Correct because Obstructive shock is due to physical flow obstruction (tamponade, tension PTX, PE) with low CO and high SVR. Definitive relief of obstruction is mandatory for recovery.', 'Shock Management - NCLEX', false, 33, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Early shock signs" in Shock Management?', 'In rapid prioritization, which statement is most consistent with "Early shock signs" in Shock Management?', '[{"id": "a", "text": "Hypotension is first sign of shock."}, {"id": "b", "text": "Bleeding source control is unnecessary."}, {"id": "c", "text": "Shock treatment begins with oral fluids only."}, {"id": "d", "text": "Tachycardia is first compensatory sign."}]'::jsonb, '["d"]'::jsonb, 'Correct because Early compensated shock shows tachycardia first, possible normal BP, cool clammy skin, tachypnea, anxiety, and slight urine decrease. Do not be reassured by normal BP when compensatory signs are present.', 'Shock Management - NCLEX', false, 34, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Late shock signs" in Shock Management would the nurse recognize as correct?', 'Which conclusion about "Late shock signs" in Shock Management would the nurse recognize as correct?', '[{"id": "a", "text": "Cardiogenic shock is treated with volume loading only."}, {"id": "b", "text": "Late shock has improving urine output."}, {"id": "c", "text": "Mottling/cyanosis and acidosis indicate decompensation."}, {"id": "d", "text": "Cardiogenic shock requires leg elevation above heart."}]'::jsonb, '["c"]'::jsonb, 'Correct because Late decompensated shock includes hypotension, altered LOC, urine output <30 mL/hr, mottled/cyanotic skin, lactic acidosis, and MODS progression. Escalate aggressively at decompensation to prevent arrest.', 'Shock Management - NCLEX', false, 35, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Shock Management note, which statement about "NCLEX early warning" is most accurate?', 'According to the Shock Management note, which statement about "NCLEX early warning" is most accurate?', '[{"id": "a", "text": "Bradycardia is first universal shock sign."}, {"id": "b", "text": "Normal BP cannot exclude early shock."}, {"id": "c", "text": "Normal BP definitively excludes shock."}, {"id": "d", "text": "Goal urine output is 0.05 mL/kg/hr."}]'::jsonb, '["b"]'::jsonb, 'Correct because NCLEX priority notes that tachycardia is first and BP drops last, so normal BP does not rule out shock. Prioritize trend recognition over single BP value.', 'Shock Management - NCLEX', false, 36, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "General initial treatment" in Shock Management. Which statement is correct?', 'The nurse is reviewing "General initial treatment" in Shock Management. Which statement is correct?', '[{"id": "a", "text": "Dobutamine alone is first-line septic pressor."}, {"id": "b", "text": "Only lipid panel is urgent."}, {"id": "c", "text": "Two large-bore IVs are recommended."}, {"id": "d", "text": "Shock treatment begins with oral fluids only."}]'::jsonb, '["c"]'::jsonb, 'Correct because General treatment includes oxygenation, large-bore IV access, continuous monitoring, urine output goals, and broad shock labs. Rapid stabilization and monitoring should start before definitive subtype treatment.', 'Shock Management - NCLEX', false, 37, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Positioning rule" in Shock Management?', 'Which clinical judgment is most accurate regarding "Positioning rule" in Shock Management?', '[{"id": "a", "text": "Shock subtype is irrelevant once oxygen is started."}, {"id": "b", "text": "Neurogenic shock requires no vasopressors."}, {"id": "c", "text": "All shock types should use strict Trendelenburg."}, {"id": "d", "text": "Leg-elevated supine is general shock position."}]'::jsonb, '["d"]'::jsonb, 'Correct because Shock positioning is generally supine with legs elevated (Trendelenburg/modified), except cardiogenic shock where HOB is elevated. Choose position by shock type to avoid worsening pulmonary congestion.', 'Shock Management - NCLEX', false, 38, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Urine output target" in Shock Management?', 'In rapid prioritization, which statement is most consistent with "Urine output target" in Shock Management?', '[{"id": "a", "text": "Vasopressors are first-line before fluids in hypovolemia."}, {"id": "b", "text": "Blood pressure normalization alone confirms full recovery."}, {"id": "c", "text": "Urine output monitoring is optional in shock."}, {"id": "d", "text": "Renal perfusion tracking is critical in shock resuscitation."}]'::jsonb, '["d"]'::jsonb, 'Correct because Foley monitoring goal is urine output greater than 0.5 mL/kg/hr. Renal perfusion tracking is critical in shock resuscitation.', 'Shock Management - NCLEX', false, 39, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Severe shock invasive monitoring" in Shock Management would the nurse recognize as correct?', 'Which conclusion about "Severe shock invasive monitoring" in Shock Management would the nurse recognize as correct?', '[{"id": "a", "text": "Blood pressure normalization alone confirms full recovery."}, {"id": "b", "text": "Cardiogenic shock is treated with volume loading only."}, {"id": "c", "text": "Invasive lines are contraindicated in severe shock."}, {"id": "d", "text": "Use invasive monitoring when rapid titration is needed."}]'::jsonb, '["d"]'::jsonb, 'Correct because Arterial and central lines are used in severe shock for close hemodynamic management. Use invasive monitoring when rapid titration is needed.', 'Shock Management - NCLEX', false, 40, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Shock Management note, which statement about "Shock lab panel" is most accurate?', 'According to the Shock Management note, which statement about "Shock lab panel" is most accurate?', '[{"id": "a", "text": "Blood pressure normalization alone confirms full recovery."}, {"id": "b", "text": "No labs are needed during shock."}, {"id": "c", "text": "Shock subtype is irrelevant once oxygen is started."}, {"id": "d", "text": "Combine perfusion, metabolic, and infectious data quickly."}]'::jsonb, '["d"]'::jsonb, 'Correct because Recommended labs include ABG, lactate, CBC, BMP, coagulation tests, and blood cultures in sepsis. Combine perfusion, metabolic, and infectious data quickly.', 'Shock Management - NCLEX', false, 41, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Hypovolemic treatment specifics" in Shock Management. Which statement is correct?', 'The nurse is reviewing "Hypovolemic treatment specifics" in Shock Management. Which statement is correct?', '[{"id": "a", "text": "Blood pressure normalization alone confirms full recovery."}, {"id": "b", "text": "Restore intravascular volume before vasoconstriction strategies."}, {"id": "c", "text": "Vasopressors are first-line before fluids in hypovolemia."}, {"id": "d", "text": "Epinephrine has no cardiovascular receptor effects."}]'::jsonb, '["b"]'::jsonb, 'Correct because Hypovolemic treatment is IV crystalloids (NS/LR), blood products if hemorrhagic, bleeding control, and delaying vasopressors until volume replacement. Restore intravascular volume before vasoconstriction strategies.', 'Shock Management - NCLEX', false, 42, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Cardiogenic treatment specifics" in Shock Management?', 'Which clinical judgment is most accurate regarding "Cardiogenic treatment specifics" in Shock Management?', '[{"id": "a", "text": "Blood pressure normalization alone confirms full recovery."}, {"id": "b", "text": "Support pump function while correcting primary cardiac pathology."}, {"id": "c", "text": "Cardiogenic shock is treated with volume loading only."}, {"id": "d", "text": "Inotropes are contraindicated in cardiogenic shock."}]'::jsonb, '["b"]'::jsonb, 'Correct because Cardiogenic management includes treating cause (e.g., PCI for MI), inotropes (dobutamine/milrinone), norepinephrine if persistent hypotension, diuretics if overloaded, and possible IABP/LVAD. Support pump function while correcting primary cardiac pathology.', 'Shock Management - NCLEX', false, 43, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Septic bundle timing" in Shock Management?', 'In rapid prioritization, which statement is most consistent with "Septic bundle timing" in Shock Management?', '[{"id": "a", "text": "Time-sensitive sepsis actions strongly influence outcomes."}, {"id": "b", "text": "Antibiotics are delayed until cultures finalize."}, {"id": "c", "text": "Shock subtype is irrelevant once oxygen is started."}, {"id": "d", "text": "Blood pressure normalization alone confirms full recovery."}]'::jsonb, '["a"]'::jsonb, 'Correct because Septic shock care includes blood cultures before antibiotics, broad-spectrum antibiotics within 1 hour, and 30 mL/kg fluid bolus within 3 hours. Time-sensitive sepsis actions strongly influence outcomes.', 'Shock Management - NCLEX', false, 44, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Septic vasopressors/steroids" in Shock Management would the nurse recognize as correct?', 'Which conclusion about "Septic vasopressors/steroids" in Shock Management would the nurse recognize as correct?', '[{"id": "a", "text": "Steroids are always first treatment before fluids."}, {"id": "b", "text": "Septic vasodilatory physiology supports pressor use."}, {"id": "c", "text": "Dobutamine alone is first-line septic pressor."}, {"id": "d", "text": "Shock subtype is irrelevant once oxygen is started."}]'::jsonb, '["b"]'::jsonb, 'Correct because Norepinephrine is first-line vasopressor in septic shock, with corticosteroids considered if refractory. Escalate pressor support and adjuncts when fluid response is inadequate.', 'Shock Management - NCLEX', false, 45, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Shock Management note, which statement about "Neurogenic treatment specifics" is most accurate?', 'According to the Shock Management note, which statement about "Neurogenic treatment specifics" is most accurate?', '[{"id": "a", "text": "Shock subtype is irrelevant once oxygen is started."}, {"id": "b", "text": "Blood pressure normalization alone confirms full recovery."}, {"id": "c", "text": "Neurogenic shock requires no vasopressors."}, {"id": "d", "text": "Neurogenic shock treatment includes cautious fluids, norepinephrine/phenylephrine, atropine for bradycardia, and spinal immobilization."}]'::jsonb, '["d"]'::jsonb, 'Correct because Neurogenic shock treatment includes cautious fluids, norepinephrine/phenylephrine, atropine for bradycardia, and spinal immobilization. Address vasodilation and bradycardia while protecting spinal injury.', 'Shock Management - NCLEX', false, 46, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Obstructive definitive care" in Shock Management. Which statement is correct?', 'The nurse is reviewing "Obstructive definitive care" in Shock Management. Which statement is correct?', '[{"id": "a", "text": "Obstructive shock is corrected by fluids alone."}, {"id": "b", "text": "PE may need thrombolytics or embolectomy."}, {"id": "c", "text": "Vasopressin is first-line bronchodilator."}, {"id": "d", "text": "Hypovolemic shock has high CO and low SVR."}]'::jsonb, '["b"]'::jsonb, 'Correct because Obstructive shock requires removing obstruction: pericardiocentesis for tamponade, needle decompression for tension PTX, and thrombolysis/embolectomy for PE. Definitive mechanical relief is essential; supportive measures alone are insufficient.', 'Shock Management - NCLEX', false, 47, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Norepinephrine profile" in Shock Management?', 'Which clinical judgment is most accurate regarding "Norepinephrine profile" in Shock Management?', '[{"id": "a", "text": "Blood pressure normalization alone confirms full recovery."}, {"id": "b", "text": "Norepinephrine acts via α1 + β1 to increase SVR with mild CO effect and is first-line for septic shock; also used in neurogenic shock."}, {"id": "c", "text": "Norepinephrine is pure β2 bronchodilator."}, {"id": "d", "text": "Shock subtype is irrelevant once oxygen is started."}]'::jsonb, '["b"]'::jsonb, 'Correct because Norepinephrine acts via α1 + β1 to increase SVR with mild CO effect and is first-line for septic shock; also used in neurogenic shock. Monitor peripheral perfusion while titrating SVR support.', 'Shock Management - NCLEX', false, 48, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Dobutamine profile" in Shock Management?', 'In rapid prioritization, which statement is most consistent with "Dobutamine profile" in Shock Management?', '[{"id": "a", "text": "Skin is cold/clammy from onset in all septic phases."}, {"id": "b", "text": "Dobutamine primarily decreases contractility."}, {"id": "c", "text": "Use inotropy to augment forward flow in pump failure."}, {"id": "d", "text": "Shock subtype is irrelevant once oxygen is started."}]'::jsonb, '["c"]'::jsonb, 'Correct because Dobutamine is a β1 inotrope increasing contractility and is used in cardiogenic shock with reduced EF. Use inotropy to augment forward flow in pump failure.', 'Shock Management - NCLEX', false, 49, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Epinephrine and vasopressin profiles" in Shock Management would the nurse recognize as correct?', 'Which conclusion about "Epinephrine and vasopressin profiles" in Shock Management would the nurse recognize as correct?', '[{"id": "a", "text": "Match pressor receptor profile to clinical indication."}, {"id": "b", "text": "Shock subtype is irrelevant once oxygen is started."}, {"id": "c", "text": "Epinephrine has no cardiovascular receptor effects."}, {"id": "d", "text": "Blood pressure normalization alone confirms full recovery."}]'::jsonb, '["a"]'::jsonb, 'Correct because Epinephrine is α1/β1/β2 and used in anaphylaxis/cardiac arrest, while vasopressin (V1) is septic add-on vasoconstrictor. Match pressor receptor profile to clinical indication.', 'Shock Management - NCLEX', false, 50, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Shock definition" in Shock Management are correct? (Select all that apply)', 'Which statements about "Shock definition" in Shock Management are correct? (Select all that apply)', '[{"id": "a", "text": "Shock is defined as isolated hypertension."}, {"id": "b", "text": "Cellular oxygen delivery is insufficient in shock."}, {"id": "c", "text": "Shock is a physiologic emergency state."}, {"id": "d", "text": "Shock reflects inadequate tissue perfusion."}, {"id": "e", "text": "Shock has no effect on oxygen delivery."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Shock is inadequate tissue perfusion causing insufficient oxygen delivery and cellular dysfunction.', 'Shock Management - NCLEX', true, 51, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Shock Management, which findings or actions relate to "Shock metabolic pathway"? (Select all that apply)', 'For Shock Management, which findings or actions relate to "Shock metabolic pathway"? (Select all that apply)', '[{"id": "a", "text": "Progression may lead to MODS."}, {"id": "b", "text": "Anaerobic metabolism occurs in shock."}, {"id": "c", "text": "Lactic acidosis is a listed consequence."}, {"id": "d", "text": "Shock cannot cause organ dysfunction."}, {"id": "e", "text": "Shock produces alkalosis from hyperperfusion."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: In shock, anaerobic metabolism develops with lactic acidosis and can progress to MODS.', 'Shock Management - NCLEX', true, 52, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Hypovolemic profile" in Shock Management? (Select all that apply)', 'The nurse is planning care. Which items apply to "Hypovolemic profile" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "CO decreases in hypovolemic shock."}, {"id": "b", "text": "JVD is classic hypovolemic finding."}, {"id": "c", "text": "Flat neck veins are listed key sign."}, {"id": "d", "text": "SVR increases compensatorily in hypovolemic shock."}, {"id": "e", "text": "Hypovolemic shock has high CO and low SVR."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Hypovolemic shock stems from blood/fluid loss with low CO, high SVR, flat neck veins, pallor, and tachycardia.', 'Shock Management - NCLEX', true, 53, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Cardiogenic profile" in Shock Management? (Select all that apply)', 'Which of the following are consistent with "Cardiogenic profile" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "Cardiogenic shock presents with flat neck veins."}, {"id": "b", "text": "Cardiogenic shock has elevated CO."}, {"id": "c", "text": "S3/frothy sputum are associated findings."}, {"id": "d", "text": "Pump failure etiology is listed for cardiogenic shock."}, {"id": "e", "text": "JVD and crackles are key signs."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Cardiogenic shock is pump failure (e.g., MI/HF/cardiomyopathy) with low CO, high SVR, JVD, crackles, S3, and frothy sputum.', 'Shock Management - NCLEX', true, 54, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Septic profile" in Shock Management? (Select all that apply)', 'During reassessment, which observations align with "Septic profile" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "CO may be high early and low late."}, {"id": "b", "text": "Septic shock always has high SVR."}, {"id": "c", "text": "Septic shock is distributive with vasodilation."}, {"id": "d", "text": "Skin is cold/clammy from onset in all septic phases."}, {"id": "e", "text": "SVR is reduced in septic shock."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Septic shock is distributive vasodilation with low SVR and warm flushed skin early; CO may be high early then low late.', 'Shock Management - NCLEX', true, 55, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Neurogenic profile" in Shock Management are correct? (Select all that apply)', 'Which statements about "Neurogenic profile" in Shock Management are correct? (Select all that apply)', '[{"id": "a", "text": "Warm dry skin below injury is listed."}, {"id": "b", "text": "Loss of sympathetic tone is mechanism."}, {"id": "c", "text": "Neurogenic shock includes bradycardia and hypotension."}, {"id": "d", "text": "Neurogenic shock has high SVR."}, {"id": "e", "text": "Neurogenic shock usually causes tachycardia."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Neurogenic shock follows spinal injury with loss of sympathetic tone causing low CO, low SVR, bradycardia, hypotension, and warm dry skin below injury.', 'Shock Management - NCLEX', true, 56, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Shock Management, which findings or actions relate to "Obstructive profile"? (Select all that apply)', 'For Shock Management, which findings or actions relate to "Obstructive profile"? (Select all that apply)', '[{"id": "a", "text": "Obstructive shock is caused by volume loss only."}, {"id": "b", "text": "Obstructive shock has high CO."}, {"id": "c", "text": "CO is reduced in obstructive shock."}, {"id": "d", "text": "Tamponade/tension PTX/PE are listed causes."}, {"id": "e", "text": "SVR is increased in obstructive shock."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Obstructive shock is due to physical flow obstruction (tamponade, tension PTX, PE) with low CO and high SVR.', 'Shock Management - NCLEX', true, 57, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Early shock signs" in Shock Management? (Select all that apply)', 'The nurse is planning care. Which items apply to "Early shock signs" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "Tachycardia is first compensatory sign."}, {"id": "b", "text": "Cool clammy skin and tachypnea are early signs."}, {"id": "c", "text": "Hypotension is first sign of shock."}, {"id": "d", "text": "Normal BP excludes early shock."}, {"id": "e", "text": "BP may still be normal early."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Early compensated shock shows tachycardia first, possible normal BP, cool clammy skin, tachypnea, anxiety, and slight urine decrease.', 'Shock Management - NCLEX', true, 58, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Late shock signs" in Shock Management? (Select all that apply)', 'Which of the following are consistent with "Late shock signs" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "Late shock preserves normal mentation."}, {"id": "b", "text": "Urine output under 30 mL/hr is late sign."}, {"id": "c", "text": "Late shock has improving urine output."}, {"id": "d", "text": "Hypotension appears in late shock."}, {"id": "e", "text": "Mottling/cyanosis and acidosis indicate decompensation."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Late decompensated shock includes hypotension, altered LOC, urine output <30 mL/hr, mottled/cyanotic skin, lactic acidosis, and MODS progression.', 'Shock Management - NCLEX', true, 59, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "NCLEX early warning" in Shock Management? (Select all that apply)', 'During reassessment, which observations align with "NCLEX early warning" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "Normal BP definitively excludes shock."}, {"id": "b", "text": "Bradycardia is first universal shock sign."}, {"id": "c", "text": "Normal BP cannot exclude early shock."}, {"id": "d", "text": "BP drop is late finding."}, {"id": "e", "text": "Tachycardia-first principle is emphasized."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: NCLEX priority notes that tachycardia is first and BP drops last, so normal BP does not rule out shock.', 'Shock Management - NCLEX', true, 60, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "General initial treatment" in Shock Management are correct? (Select all that apply)', 'Which statements about "General initial treatment" in Shock Management are correct? (Select all that apply)', '[{"id": "a", "text": "Monitoring can be delayed until subtype confirmed."}, {"id": "b", "text": "Two large-bore IVs are recommended."}, {"id": "c", "text": "Shock treatment begins with oral fluids only."}, {"id": "d", "text": "High-flow oxygen is listed in initial management."}, {"id": "e", "text": "Continuous vitals/SpO2/urine monitoring is required."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: General treatment includes oxygenation, large-bore IV access, continuous monitoring, urine output goals, and broad shock labs.', 'Shock Management - NCLEX', true, 61, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Shock Management, which findings or actions relate to "Positioning rule"? (Select all that apply)', 'For Shock Management, which findings or actions relate to "Positioning rule"? (Select all that apply)', '[{"id": "a", "text": "Cardiogenic shock is exception with HOB elevation."}, {"id": "b", "text": "Leg-elevated supine is general shock position."}, {"id": "c", "text": "Cardiogenic shock requires leg elevation above heart."}, {"id": "d", "text": "All shock types should use strict Trendelenburg."}, {"id": "e", "text": "Positioning differs by hemodynamic context."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Shock positioning is generally supine with legs elevated (Trendelenburg/modified), except cardiogenic shock where HOB is elevated.', 'Shock Management - NCLEX', true, 62, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Urine output target" in Shock Management? (Select all that apply)', 'The nurse is planning care. Which items apply to "Urine output target" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "Low output suggests perfusion compromise."}, {"id": "b", "text": "Urine output monitoring is optional in shock."}, {"id": "c", "text": "Goal urine output is 0.05 mL/kg/hr."}, {"id": "d", "text": "Foley is recommended for hourly urine monitoring."}, {"id": "e", "text": "Goal >0.5 mL/kg/hr is listed."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Foley monitoring goal is urine output greater than 0.5 mL/kg/hr.', 'Shock Management - NCLEX', true, 63, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Severe shock invasive monitoring" in Shock Management? (Select all that apply)', 'Which of the following are consistent with "Severe shock invasive monitoring" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "Only pulse oximetry is needed in severe shock."}, {"id": "b", "text": "Arterial line is listed in severe shock."}, {"id": "c", "text": "Central line is listed in severe shock."}, {"id": "d", "text": "Invasive monitoring supports advanced management."}, {"id": "e", "text": "Invasive lines are contraindicated in severe shock."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Arterial and central lines are used in severe shock for close hemodynamic management.', 'Shock Management - NCLEX', true, 64, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Shock lab panel" in Shock Management? (Select all that apply)', 'During reassessment, which observations align with "Shock lab panel" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "Blood cultures are included for sepsis context."}, {"id": "b", "text": "Only lipid panel is urgent."}, {"id": "c", "text": "ABG and lactate are listed labs."}, {"id": "d", "text": "No labs are needed during shock."}, {"id": "e", "text": "CBC/BMP/coags are listed labs."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Recommended labs include ABG, lactate, CBC, BMP, coagulation tests, and blood cultures in sepsis.', 'Shock Management - NCLEX', true, 65, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Hypovolemic treatment specifics" in Shock Management are correct? (Select all that apply)', 'Which statements about "Hypovolemic treatment specifics" in Shock Management are correct? (Select all that apply)', '[{"id": "a", "text": "NS/LR fluid resuscitation is listed."}, {"id": "b", "text": "Bleeding source control is unnecessary."}, {"id": "c", "text": "PRBC/FFP used in hemorrhagic shock."}, {"id": "d", "text": "Vasopressors are first-line before fluids in hypovolemia."}, {"id": "e", "text": "No vasopressors before adequate volume is key point."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Hypovolemic treatment is IV crystalloids (NS/LR), blood products if hemorrhagic, bleeding control, and delaying vasopressors until volume replacement.', 'Shock Management - NCLEX', true, 66, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Shock Management, which findings or actions relate to "Cardiogenic treatment specifics"? (Select all that apply)', 'For Shock Management, which findings or actions relate to "Cardiogenic treatment specifics"? (Select all that apply)', '[{"id": "a", "text": "Inotropes are contraindicated in cardiogenic shock."}, {"id": "b", "text": "Norepinephrine may be added if hypotension persists."}, {"id": "c", "text": "Cardiogenic shock is treated with volume loading only."}, {"id": "d", "text": "IABP/LVAD are listed for refractory cases."}, {"id": "e", "text": "Dobutamine/milrinone are listed inotropes."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Cardiogenic management includes treating cause (e.g., PCI for MI), inotropes (dobutamine/milrinone), norepinephrine if persistent hypotension, diuretics if overloaded, and possible IABP/LVAD.', 'Shock Management - NCLEX', true, 67, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Septic bundle timing" in Shock Management? (Select all that apply)', 'The nurse is planning care. Which items apply to "Septic bundle timing" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "Antibiotics are given within one hour."}, {"id": "b", "text": "Fluid bolus is contraindicated in septic shock."}, {"id": "c", "text": "30 mL/kg bolus within 3 hours is listed."}, {"id": "d", "text": "Cultures are obtained before antibiotics."}, {"id": "e", "text": "Antibiotics are delayed until cultures finalize."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Septic shock care includes blood cultures before antibiotics, broad-spectrum antibiotics within 1 hour, and 30 mL/kg fluid bolus within 3 hours.', 'Shock Management - NCLEX', true, 68, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Septic vasopressors/steroids" in Shock Management? (Select all that apply)', 'Which of the following are consistent with "Septic vasopressors/steroids" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "Steroids are considered in refractory septic shock."}, {"id": "b", "text": "Norepinephrine first-line is explicitly listed."}, {"id": "c", "text": "Dobutamine alone is first-line septic pressor."}, {"id": "d", "text": "Septic vasodilatory physiology supports pressor use."}, {"id": "e", "text": "Steroids are always first treatment before fluids."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Norepinephrine is first-line vasopressor in septic shock, with corticosteroids considered if refractory.', 'Shock Management - NCLEX', true, 69, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Neurogenic treatment specifics" in Shock Management? (Select all that apply)', 'During reassessment, which observations align with "Neurogenic treatment specifics" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "Neurogenic shock requires no vasopressors."}, {"id": "b", "text": "Spinal immobilization is listed intervention."}, {"id": "c", "text": "Norepinephrine/phenylephrine are listed pressors."}, {"id": "d", "text": "Tachycardia treatment is atropine goal."}, {"id": "e", "text": "Atropine for bradycardia is listed."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Neurogenic shock treatment includes cautious fluids, norepinephrine/phenylephrine, atropine for bradycardia, and spinal immobilization.', 'Shock Management - NCLEX', true, 70, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Obstructive definitive care" in Shock Management are correct? (Select all that apply)', 'Which statements about "Obstructive definitive care" in Shock Management are correct? (Select all that apply)', '[{"id": "a", "text": "Obstructive shock is corrected by fluids alone."}, {"id": "b", "text": "Tension PTX needs needle decompression at 2nd ICS MCL."}, {"id": "c", "text": "PE may need thrombolytics or embolectomy."}, {"id": "d", "text": "Tamponade requires pericardiocentesis."}, {"id": "e", "text": "Pericardiocentesis is contraindicated in tamponade."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Obstructive shock requires removing obstruction: pericardiocentesis for tamponade, needle decompression for tension PTX, and thrombolysis/embolectomy for PE.', 'Shock Management - NCLEX', true, 71, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Shock Management, which findings or actions relate to "Norepinephrine profile"? (Select all that apply)', 'For Shock Management, which findings or actions relate to "Norepinephrine profile"? (Select all that apply)', '[{"id": "a", "text": "α1 + β1 mechanism is listed."}, {"id": "b", "text": "First-line in septic shock is listed."}, {"id": "c", "text": "Norepinephrine is pure β2 bronchodilator."}, {"id": "d", "text": "Norepinephrine lowers SVR."}, {"id": "e", "text": "Neurogenic use is listed."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Norepinephrine acts via α1 + β1 to increase SVR with mild CO effect and is first-line for septic shock; also used in neurogenic shock.', 'Shock Management - NCLEX', true, 72, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Dobutamine profile" in Shock Management? (Select all that apply)', 'The nurse is planning care. Which items apply to "Dobutamine profile" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "It increases contractility."}, {"id": "b", "text": "Dobutamine primarily decreases contractility."}, {"id": "c", "text": "Dobutamine is first-line for anaphylaxis."}, {"id": "d", "text": "Used for cardiogenic shock with low EF."}, {"id": "e", "text": "Dobutamine is β1 inotrope in note."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Dobutamine is a β1 inotrope increasing contractility and is used in cardiogenic shock with reduced EF.', 'Shock Management - NCLEX', true, 73, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Epinephrine and vasopressin profiles" in Shock Management? (Select all that apply)', 'Which of the following are consistent with "Epinephrine and vasopressin profiles" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "Epinephrine has no cardiovascular receptor effects."}, {"id": "b", "text": "Vasopressin is septic add-on via V1 vasoconstriction."}, {"id": "c", "text": "Epinephrine has alpha/beta effects in note."}, {"id": "d", "text": "Vasopressin is first-line bronchodilator."}, {"id": "e", "text": "Epinephrine indications include anaphylaxis/cardiac arrest."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Epinephrine is α1/β1/β2 and used in anaphylaxis/cardiac arrest, while vasopressin (V1) is septic add-on vasoconstrictor.', 'Shock Management - NCLEX', true, 74, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Shock-type mnemonic" in Shock Management? (Select all that apply)', 'During reassessment, which observations align with "Shock-type mnemonic" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "Distributive is blocked exit."}, {"id": "b", "text": "Cardiogenic is broken pump."}, {"id": "c", "text": "Cardiogenic is leaky pipes."}, {"id": "d", "text": "Hypovolemic is described as empty tank."}, {"id": "e", "text": "Obstructive is blocked exit."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Mnemonic in note: H hypovolemic (empty tank), C cardiogenic (broken pump), D distributive (leaky pipes), O obstructive (blocked exit).', 'Shock Management - NCLEX', true, 75, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Integrated NCLEX triage" in Shock Management are correct? (Select all that apply)', 'Which statements about "Integrated NCLEX triage" in Shock Management are correct? (Select all that apply)', '[{"id": "a", "text": "All shock is treated identically long-term."}, {"id": "b", "text": "Subtype-specific therapy is required after initial stabilization."}, {"id": "c", "text": "Delayed recognition increases MODS risk."}, {"id": "d", "text": "Hypotension must appear before any intervention."}, {"id": "e", "text": "Compensated shock can present before BP drop."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Early shock recognition hinges on tachycardia/tachypnea/anxiety before hypotension, with subtype-targeted definitive management thereafter.', 'Shock Management - NCLEX', true, 76, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Shock Management, which findings or actions relate to "Shock definition"? (Select all that apply)', 'For Shock Management, which findings or actions relate to "Shock definition"? (Select all that apply)', '[{"id": "a", "text": "Cellular oxygen delivery is insufficient in shock."}, {"id": "b", "text": "Shock is defined as isolated hypertension."}, {"id": "c", "text": "Shock reflects inadequate tissue perfusion."}, {"id": "d", "text": "Shock has no effect on oxygen delivery."}, {"id": "e", "text": "Shock is a physiologic emergency state."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Shock is inadequate tissue perfusion causing insufficient oxygen delivery and cellular dysfunction.', 'Shock Management - NCLEX', true, 77, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Shock metabolic pathway" in Shock Management? (Select all that apply)', 'The nurse is planning care. Which items apply to "Shock metabolic pathway" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "Shock produces alkalosis from hyperperfusion."}, {"id": "b", "text": "Shock cannot cause organ dysfunction."}, {"id": "c", "text": "Progression may lead to MODS."}, {"id": "d", "text": "Anaerobic metabolism occurs in shock."}, {"id": "e", "text": "Lactic acidosis is a listed consequence."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: In shock, anaerobic metabolism develops with lactic acidosis and can progress to MODS.', 'Shock Management - NCLEX', true, 78, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Hypovolemic profile" in Shock Management? (Select all that apply)', 'Which of the following are consistent with "Hypovolemic profile" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "SVR increases compensatorily in hypovolemic shock."}, {"id": "b", "text": "CO decreases in hypovolemic shock."}, {"id": "c", "text": "Hypovolemic shock has high CO and low SVR."}, {"id": "d", "text": "Flat neck veins are listed key sign."}, {"id": "e", "text": "JVD is classic hypovolemic finding."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Hypovolemic shock stems from blood/fluid loss with low CO, high SVR, flat neck veins, pallor, and tachycardia.', 'Shock Management - NCLEX', true, 79, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Cardiogenic profile" in Shock Management? (Select all that apply)', 'During reassessment, which observations align with "Cardiogenic profile" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "JVD and crackles are key signs."}, {"id": "b", "text": "Pump failure etiology is listed for cardiogenic shock."}, {"id": "c", "text": "Cardiogenic shock presents with flat neck veins."}, {"id": "d", "text": "Cardiogenic shock has elevated CO."}, {"id": "e", "text": "S3/frothy sputum are associated findings."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Cardiogenic shock is pump failure (e.g., MI/HF/cardiomyopathy) with low CO, high SVR, JVD, crackles, S3, and frothy sputum.', 'Shock Management - NCLEX', true, 80, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Septic profile" in Shock Management are correct? (Select all that apply)', 'Which statements about "Septic profile" in Shock Management are correct? (Select all that apply)', '[{"id": "a", "text": "Skin is cold/clammy from onset in all septic phases."}, {"id": "b", "text": "Septic shock always has high SVR."}, {"id": "c", "text": "CO may be high early and low late."}, {"id": "d", "text": "SVR is reduced in septic shock."}, {"id": "e", "text": "Septic shock is distributive with vasodilation."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Septic shock is distributive vasodilation with low SVR and warm flushed skin early; CO may be high early then low late.', 'Shock Management - NCLEX', true, 81, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Shock Management, which findings or actions relate to "Neurogenic profile"? (Select all that apply)', 'For Shock Management, which findings or actions relate to "Neurogenic profile"? (Select all that apply)', '[{"id": "a", "text": "Warm dry skin below injury is listed."}, {"id": "b", "text": "Neurogenic shock includes bradycardia and hypotension."}, {"id": "c", "text": "Neurogenic shock usually causes tachycardia."}, {"id": "d", "text": "Neurogenic shock has high SVR."}, {"id": "e", "text": "Loss of sympathetic tone is mechanism."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Neurogenic shock follows spinal injury with loss of sympathetic tone causing low CO, low SVR, bradycardia, hypotension, and warm dry skin below injury.', 'Shock Management - NCLEX', true, 82, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Obstructive profile" in Shock Management? (Select all that apply)', 'The nurse is planning care. Which items apply to "Obstructive profile" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "Tamponade/tension PTX/PE are listed causes."}, {"id": "b", "text": "Obstructive shock has high CO."}, {"id": "c", "text": "CO is reduced in obstructive shock."}, {"id": "d", "text": "Obstructive shock is caused by volume loss only."}, {"id": "e", "text": "SVR is increased in obstructive shock."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Obstructive shock is due to physical flow obstruction (tamponade, tension PTX, PE) with low CO and high SVR.', 'Shock Management - NCLEX', true, 83, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Early shock signs" in Shock Management? (Select all that apply)', 'Which of the following are consistent with "Early shock signs" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "Cool clammy skin and tachypnea are early signs."}, {"id": "b", "text": "Tachycardia is first compensatory sign."}, {"id": "c", "text": "Hypotension is first sign of shock."}, {"id": "d", "text": "BP may still be normal early."}, {"id": "e", "text": "Normal BP excludes early shock."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Early compensated shock shows tachycardia first, possible normal BP, cool clammy skin, tachypnea, anxiety, and slight urine decrease.', 'Shock Management - NCLEX', true, 84, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Late shock signs" in Shock Management? (Select all that apply)', 'During reassessment, which observations align with "Late shock signs" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "Hypotension appears in late shock."}, {"id": "b", "text": "Mottling/cyanosis and acidosis indicate decompensation."}, {"id": "c", "text": "Late shock preserves normal mentation."}, {"id": "d", "text": "Urine output under 30 mL/hr is late sign."}, {"id": "e", "text": "Late shock has improving urine output."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Late decompensated shock includes hypotension, altered LOC, urine output <30 mL/hr, mottled/cyanotic skin, lactic acidosis, and MODS progression.', 'Shock Management - NCLEX', true, 85, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "NCLEX early warning" in Shock Management are correct? (Select all that apply)', 'Which statements about "NCLEX early warning" in Shock Management are correct? (Select all that apply)', '[{"id": "a", "text": "Normal BP cannot exclude early shock."}, {"id": "b", "text": "Normal BP definitively excludes shock."}, {"id": "c", "text": "Bradycardia is first universal shock sign."}, {"id": "d", "text": "Tachycardia-first principle is emphasized."}, {"id": "e", "text": "BP drop is late finding."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: NCLEX priority notes that tachycardia is first and BP drops last, so normal BP does not rule out shock.', 'Shock Management - NCLEX', true, 86, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Shock Management, which findings or actions relate to "General initial treatment"? (Select all that apply)', 'For Shock Management, which findings or actions relate to "General initial treatment"? (Select all that apply)', '[{"id": "a", "text": "High-flow oxygen is listed in initial management."}, {"id": "b", "text": "Two large-bore IVs are recommended."}, {"id": "c", "text": "Shock treatment begins with oral fluids only."}, {"id": "d", "text": "Continuous vitals/SpO2/urine monitoring is required."}, {"id": "e", "text": "Monitoring can be delayed until subtype confirmed."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: General treatment includes oxygenation, large-bore IV access, continuous monitoring, urine output goals, and broad shock labs.', 'Shock Management - NCLEX', true, 87, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Positioning rule" in Shock Management? (Select all that apply)', 'The nurse is planning care. Which items apply to "Positioning rule" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "Leg-elevated supine is general shock position."}, {"id": "b", "text": "Cardiogenic shock is exception with HOB elevation."}, {"id": "c", "text": "All shock types should use strict Trendelenburg."}, {"id": "d", "text": "Positioning differs by hemodynamic context."}, {"id": "e", "text": "Cardiogenic shock requires leg elevation above heart."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Shock positioning is generally supine with legs elevated (Trendelenburg/modified), except cardiogenic shock where HOB is elevated.', 'Shock Management - NCLEX', true, 88, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Urine output target" in Shock Management? (Select all that apply)', 'Which of the following are consistent with "Urine output target" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "Urine output monitoring is optional in shock."}, {"id": "b", "text": "Low output suggests perfusion compromise."}, {"id": "c", "text": "Goal urine output is 0.05 mL/kg/hr."}, {"id": "d", "text": "Foley is recommended for hourly urine monitoring."}, {"id": "e", "text": "Goal >0.5 mL/kg/hr is listed."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Foley monitoring goal is urine output greater than 0.5 mL/kg/hr.', 'Shock Management - NCLEX', true, 89, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Severe shock invasive monitoring" in Shock Management? (Select all that apply)', 'During reassessment, which observations align with "Severe shock invasive monitoring" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "Invasive lines are contraindicated in severe shock."}, {"id": "b", "text": "Arterial line is listed in severe shock."}, {"id": "c", "text": "Invasive monitoring supports advanced management."}, {"id": "d", "text": "Central line is listed in severe shock."}, {"id": "e", "text": "Only pulse oximetry is needed in severe shock."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Arterial and central lines are used in severe shock for close hemodynamic management.', 'Shock Management - NCLEX', true, 90, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Shock lab panel" in Shock Management are correct? (Select all that apply)', 'Which statements about "Shock lab panel" in Shock Management are correct? (Select all that apply)', '[{"id": "a", "text": "Only lipid panel is urgent."}, {"id": "b", "text": "No labs are needed during shock."}, {"id": "c", "text": "CBC/BMP/coags are listed labs."}, {"id": "d", "text": "Blood cultures are included for sepsis context."}, {"id": "e", "text": "ABG and lactate are listed labs."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Recommended labs include ABG, lactate, CBC, BMP, coagulation tests, and blood cultures in sepsis.', 'Shock Management - NCLEX', true, 91, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Shock Management, which findings or actions relate to "Hypovolemic treatment specifics"? (Select all that apply)', 'For Shock Management, which findings or actions relate to "Hypovolemic treatment specifics"? (Select all that apply)', '[{"id": "a", "text": "Vasopressors are first-line before fluids in hypovolemia."}, {"id": "b", "text": "NS/LR fluid resuscitation is listed."}, {"id": "c", "text": "Bleeding source control is unnecessary."}, {"id": "d", "text": "PRBC/FFP used in hemorrhagic shock."}, {"id": "e", "text": "No vasopressors before adequate volume is key point."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Hypovolemic treatment is IV crystalloids (NS/LR), blood products if hemorrhagic, bleeding control, and delaying vasopressors until volume replacement.', 'Shock Management - NCLEX', true, 92, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Cardiogenic treatment specifics" in Shock Management? (Select all that apply)', 'The nurse is planning care. Which items apply to "Cardiogenic treatment specifics" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "Cardiogenic shock is treated with volume loading only."}, {"id": "b", "text": "Dobutamine/milrinone are listed inotropes."}, {"id": "c", "text": "Inotropes are contraindicated in cardiogenic shock."}, {"id": "d", "text": "IABP/LVAD are listed for refractory cases."}, {"id": "e", "text": "Norepinephrine may be added if hypotension persists."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Cardiogenic management includes treating cause (e.g., PCI for MI), inotropes (dobutamine/milrinone), norepinephrine if persistent hypotension, diuretics if overloaded, and possible IABP/LVAD.', 'Shock Management - NCLEX', true, 93, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Septic bundle timing" in Shock Management? (Select all that apply)', 'Which of the following are consistent with "Septic bundle timing" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "30 mL/kg bolus within 3 hours is listed."}, {"id": "b", "text": "Cultures are obtained before antibiotics."}, {"id": "c", "text": "Antibiotics are given within one hour."}, {"id": "d", "text": "Fluid bolus is contraindicated in septic shock."}, {"id": "e", "text": "Antibiotics are delayed until cultures finalize."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Septic shock care includes blood cultures before antibiotics, broad-spectrum antibiotics within 1 hour, and 30 mL/kg fluid bolus within 3 hours.', 'Shock Management - NCLEX', true, 94, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Septic vasopressors/steroids" in Shock Management? (Select all that apply)', 'During reassessment, which observations align with "Septic vasopressors/steroids" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "Dobutamine alone is first-line septic pressor."}, {"id": "b", "text": "Steroids are considered in refractory septic shock."}, {"id": "c", "text": "Steroids are always first treatment before fluids."}, {"id": "d", "text": "Norepinephrine first-line is explicitly listed."}, {"id": "e", "text": "Septic vasodilatory physiology supports pressor use."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Norepinephrine is first-line vasopressor in septic shock, with corticosteroids considered if refractory.', 'Shock Management - NCLEX', true, 95, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Neurogenic treatment specifics" in Shock Management are correct? (Select all that apply)', 'Which statements about "Neurogenic treatment specifics" in Shock Management are correct? (Select all that apply)', '[{"id": "a", "text": "Atropine for bradycardia is listed."}, {"id": "b", "text": "Tachycardia treatment is atropine goal."}, {"id": "c", "text": "Spinal immobilization is listed intervention."}, {"id": "d", "text": "Neurogenic shock requires no vasopressors."}, {"id": "e", "text": "Norepinephrine/phenylephrine are listed pressors."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Neurogenic shock treatment includes cautious fluids, norepinephrine/phenylephrine, atropine for bradycardia, and spinal immobilization.', 'Shock Management - NCLEX', true, 96, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Shock Management, which findings or actions relate to "Obstructive definitive care"? (Select all that apply)', 'For Shock Management, which findings or actions relate to "Obstructive definitive care"? (Select all that apply)', '[{"id": "a", "text": "Tamponade requires pericardiocentesis."}, {"id": "b", "text": "PE may need thrombolytics or embolectomy."}, {"id": "c", "text": "Obstructive shock is corrected by fluids alone."}, {"id": "d", "text": "Pericardiocentesis is contraindicated in tamponade."}, {"id": "e", "text": "Tension PTX needs needle decompression at 2nd ICS MCL."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Obstructive shock requires removing obstruction: pericardiocentesis for tamponade, needle decompression for tension PTX, and thrombolysis/embolectomy for PE.', 'Shock Management - NCLEX', true, 97, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Norepinephrine profile" in Shock Management? (Select all that apply)', 'The nurse is planning care. Which items apply to "Norepinephrine profile" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "First-line in septic shock is listed."}, {"id": "b", "text": "α1 + β1 mechanism is listed."}, {"id": "c", "text": "Norepinephrine is pure β2 bronchodilator."}, {"id": "d", "text": "Neurogenic use is listed."}, {"id": "e", "text": "Norepinephrine lowers SVR."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Norepinephrine acts via α1 + β1 to increase SVR with mild CO effect and is first-line for septic shock; also used in neurogenic shock.', 'Shock Management - NCLEX', true, 98, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Dobutamine profile" in Shock Management? (Select all that apply)', 'Which of the following are consistent with "Dobutamine profile" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "Dobutamine primarily decreases contractility."}, {"id": "b", "text": "Dobutamine is β1 inotrope in note."}, {"id": "c", "text": "Dobutamine is first-line for anaphylaxis."}, {"id": "d", "text": "It increases contractility."}, {"id": "e", "text": "Used for cardiogenic shock with low EF."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Dobutamine is a β1 inotrope increasing contractility and is used in cardiogenic shock with reduced EF.', 'Shock Management - NCLEX', true, 99, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Epinephrine and vasopressin profiles" in Shock Management? (Select all that apply)', 'During reassessment, which observations align with "Epinephrine and vasopressin profiles" in Shock Management? (Select all that apply)', '[{"id": "a", "text": "Vasopressin is first-line bronchodilator."}, {"id": "b", "text": "Epinephrine has alpha/beta effects in note."}, {"id": "c", "text": "Vasopressin is septic add-on via V1 vasoconstriction."}, {"id": "d", "text": "Epinephrine has no cardiovascular receptor effects."}, {"id": "e", "text": "Epinephrine indications include anaphylaxis/cardiac arrest."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Epinephrine is α1/β1/β2 and used in anaphylaxis/cardiac arrest, while vasopressin (V1) is septic add-on vasoconstrictor.', 'Shock Management - NCLEX', true, 100, 1, true);
END $$;
